1	/**
2	 * Test-only direct-agent turn driver shared by assembled Loader fixtures.
3	 * @module @deepseek-ai/dsh-loader-smoke/agent-turn
4	 */
5	
6	import type { Context } from '@deepseek-ai/cordis'
7	import type { Agent } from '@deepseek-ai/dsh-agent'
8	import { createUserMessage, type TokenUsage } from '@deepseek-ai/dsh-llm'
9	import type { SessionEvent } from '@deepseek-ai/dsh-session'
10	
11	/** Result envelope consumed only by snapshot and composition tests. */
12	export interface FixtureTurnResult {
13	  readonly type: 'result'
14	  readonly sessionId: string
15	  readonly output: string
16	  readonly usage?: TokenUsage
17	}
18	
19	/** Options for one fixture turn against exactly one configured root agent. */
20	export interface FixtureTurnOptions {
21	  readonly task: string
22	  readonly onEvent?: (sessionId: string, event: SessionEvent) => void
23	}
24	
25	function addUsage(total: TokenUsage | undefined, step: TokenUsage): TokenUsage {
26	  const next: TokenUsage = {
27	    inputTokens: (total?.inputTokens ?? 0) + step.inputTokens,
28	    outputTokens: (total?.outputTokens ?? 0) + step.outputTokens,
29	  }
30	  for (const key of ['cacheReadTokens', 'cacheWriteTokens', 'reasoningTokens'] as const) {
31	    if (total?.[key] !== undefined || step[key] !== undefined) next[key] = (total?.[key] ?? 0) + (step[key] ?? 0)
32	  }
33	  return next
34	}
35	
36	function assistantText(event: Extract<SessionEvent, { type: 'assistant/message' }>): string | undefined {
37	  const blocks = event.data.message.content.filter(block => block.type === 'text')
38	  return blocks.length === 0 ? undefined : blocks.map(block => block.text).join('')
39	}
40	
41	function onlyRootAgent(ctx: Context): Agent {
42	  const agents = ctx.get('agents')?.roots() ?? []
43	  const [agent] = agents
44	  if (agent === undefined || agents.length !== 1) {
45	    throw new Error(`fixture turn requires exactly one top-level agent, found ${agents.length}`)
46	  }
47	  return agent
48	}
49	
50	/**
51	 * Drive one task from its durable inbox receipt through whole-agent idle.
52	 * @param ctx - settled Loader context with exactly one configured root agent.
53	 * @param options - task and optional canonical-event observer.
54	 * @returns the final assistant text and accumulated model usage.
55	 */
56	export async function runFixtureTurn(ctx: Context, options: FixtureTurnOptions): Promise<FixtureTurnResult> {
57	  const agent = onlyRootAgent(ctx)
58	  await agent.whenIdle()
59	
60	  const message = createUserMessage({
61	    content: [{ type: 'text', text: options.task }],
62	    source: { kind: 'user' },
63	  })
64	  let received = false
65	  let output = ''
66	  const usageByStep = new Map<string, TokenUsage>()
67	  const disposeListener = ctx.on('session/event', (session, event) => {
68	    if (session !== agent.session) return
69	    if (!received) {
70	      if (event.type !== 'agent/inbox/spliced'
71	        || !event.data.inserted.some(inserted => inserted.id === message.id)) return
72	      received = true
73	    }
74	    options.onEvent?.(session.id, event)
75	    if (event.type === 'assistant/chunk' && event.data.chunk.type === 'usage') {
76	      usageByStep.set(`${event.data.turn}/${event.data.step}`, event.data.chunk.usage)
77	    }
78	    if (event.type === 'assistant/message') {
79	      output = assistantText(event) ?? output
80	      if (event.data.usage !== undefined) {
81	        usageByStep.set(`${event.data.turn}/${event.data.step}`, event.data.usage)
82	      }
83	    }
84	  })
85	
86	  try {
87	    agent.followup(message)
88	    await agent.whenIdle()
89	  } finally {
90	    disposeListener()
91	  }
92	  await ctx.sessions.flush(agent.session)
93	  const usage = [...usageByStep.values()].reduce<TokenUsage | undefined>(addUsage, undefined)
94	  return {
95	    type: 'result',
96	    sessionId: agent.session.id,
97	    output,
98	    ...usage === undefined ? {} : { usage },
99	  }
100	}
